mapper.select:
SELECT *
, (SELECT COUNT(*) FROM shopion.tPrfDept C WHERE C.BranchId = shopion.tPrfDept.BranchId AND C.ParentDeptCode = shopion.tPrfDept.DeptCode) AS ChildCount
FROM shopion.tPrfDept

    AND BranchId = #{pBranchId}

        AND ParentDeptCode = #{pParentDeptCode}
        AND DeptLevel = 0
        AND DeptCode = #{pDeptCode}

SELECT COUNT(*)
FROM shopion.tPrfDept

    AND BranchId = #{pBranchId}
    AND ParentDeptCode = #{pParentDeptCode}
    AND DeptLevel = 0
    AND DeptCode = #{pDeptCode}

SELECT IFNULL(MAX(DeptCode),'')
FROM shopion.tPrfDept

    AND BranchId = #{branchId}
    AND ParentDeptCode = #{parentDeptCode}
    AND DeptLevel = 0
